B=[['拉丁 liber，属格 libri','书；这个词也曾指树的内皮']]
L=B+[['拉丁 librarius → librarium／libraria','与书有关 → 书柜、藏书处等'],['法语 librarie／librairie → 中古英语 librarie','藏书或藏书的地方'],['英语 library','图书馆；供查找和使用的资料集合']]
LI=B+[['拉丁 libellus','小书、小册子；书面请求或控告'],['古法语 libelle → 英语 libel','书面陈述，后来出现毁损名誉的陈述义']]
LT=B+[['意大利语 libro → libretto','书 → 小册子'],['英语 libretto','歌剧等作品的文字脚本']]
W=[
E('library','英 /ˈlaɪbrəri/；美 /ˈlaɪbreri/','图书馆；藏书；资料库、程序库','把很多可供查找和使用的东西，按一定方式收在一起。','来自拉丁 liber“书”这一族，经法语传入。不是 liberty“自由”加后缀，二者拉丁源词不同。',L,'library 最容易想到图书馆，但核心不一定是“一栋有书的楼”。a music library 可以是一批可调用的音乐，a software library 是程序可使用的一组功能。它们都保留了“收好一批资料或资源，供人取用”的组织方式。','a public library；a library card；a digital library；a software library。','library 是图书馆或资料集合；bookshop／bookstore 是书店。法语 librairie 常是书店，不能只凭相似拼写照搬。',('I borrowed two books from the local library.','我从当地的图书馆借了两本书。'),('The app uses a library of sounds recorded outdoors.','这个应用使用了一套在户外录制的声音素材库。'),sources=['https://www.etymonline.com/word/library','https://en.wiktionary.org/wiki/library']),
E('librarian','英 /laɪˈbreəriən/；美 /laɪˈbreriən/','图书馆员；图书馆专业工作人员','帮助把资料整理好，也帮助读者找到真正需要的信息的人。','library + 表示相关人员的 -an；拼写变为 librarian。早期还有抄书人的用法，现代主要指图书馆工作者。',L+[['library + -an → librarian','负责图书馆资料与服务的人']],'librarian 不只是把书摆回架子上的人。这个职业也涉及分类、检索、选书、数字资源和读者服务。想找某个主题的可靠资料，ask a librarian 是请相关专业人员帮你找路径。','a school librarian；ask the librarian；a reference librarian。','librarian 是职业；library 是机构或资料库。librarian 不等于书店售货员，也不等于所有写书的人。',('The librarian helped me find sources for my essay.','图书馆员帮我找到了写论文需要的资料。'),('Our school librarian runs a weekly reading club.','我们学校的图书馆员每周组织一次读书会。'),sources=['https://www.etymonline.com/word/librarian','https://en.wiktionary.org/wiki/librarian']),
E('librarianship','英 /laɪˈbreəriənʃɪp/；美 /laɪˈbreriənʃɪp/','图书馆员职业；图书馆专业工作与业务','把“一个馆员”放大成一整套职业实践：怎样组织资料、提供检索和服务。','librarian + -ship；-ship 在这里表示职业、身份或相关工作，不是船。',L+[['英语 librarian','图书馆员'],['librarian + -ship → librarianship','馆员职业与专业实践']],'librarianship 常用来谈图书馆这门职业及其工作方式。a career in librarianship 是从事图书馆专业工作；digital librarianship 则把注意力放到数字资源的组织与服务上。它不是一本书，也不是一个图书馆员的复数。','a career in librarianship；professional librarianship；digital librarianship。','library science 常突出研究和学科；librarianship 常突出职业与实践。实际机构的课程名称可能交叉使用。',('She became interested in librarianship while volunteering at a school library.','她在学校图书馆做志愿者时，对图书馆专业工作产生了兴趣。'),('The course introduces students to digital librarianship.','这门课向学生介绍数字图书馆业务。'),sources=['https://www.merriam-webster.com/dictionary/librarianship','https://en.wiktionary.org/wiki/librarianship']),
E('libel','/ˈlaɪbəl/','诽谤性文字；书面诽谤；以文字诽谤','原本只是“小册子、书面陈述”，后来一条常用支线变成用发表的内容毁损别人的名誉。','拉丁 liber“书”的小称是 libellus“小册子”；经古法语 libelle 进入英语。不能拆成 lie + bell。',LI,'libel 的历史说明：词的现代负面意义不一定从源头就有。小册子可以承载请求、控告，也可能承载诽谤，后一个方向后来成为常见意思。今天读新闻见到 sue for libel，重点是针对损害名誉的发表内容提起诉讼，不是“告别人写了小书”。','sue for libel；a libel action；libel someone。','日常词义区分中，libel 常说书面或发表形式的诽谤，slander 常说口头诽谤；criticism 是批评，本身不等于诽谤。',('The newspaper was sued for libel after publishing the allegation.','报纸刊登那项指控后，被提起诽谤诉讼。'),('The novel follows a reporter accused of libeling a local businessman.','这部小说讲述一位记者被指控以文字诽谤当地商人的故事。'),sources=['https://www.etymonline.com/word/libel','https://en.wiktionary.org/wiki/libel']),
E('libelous','/ˈlaɪbələs/','诽谤性的〔美式常用拼写〕','描述一段发表的内容时，强调它带有损害别人名誉的诽谤性质。','libel + -ous“具有……性质的”。不把 -ous 当作另一个独立词根。',LI+[['英语 libel + -ous → libelous','具有诽谤性质的']],'libelous 通常修饰 statement、article、claim 等，指内容具有诽谤性。这个词比 rude“无礼”或 insulting“侮辱性的”更具体，不是看到一句难听的话就可以随手换成 libelous。','a libelous statement；a libelous article；allegedly libelous material。','libel 是名词或动词，libelous 是形容词。libellous 是英式常见的双 l 拼写，意思一样。',('The editor asked the lawyer to review the allegedly libelous passage.','编辑请律师审查那段被指涉嫌诽谤的文字。'),('In the story, a libelous article ruins the actor’s reputation.','故事里，一篇诽谤文章毁掉了那位演员的名誉。'),sources=['https://www.etymonline.com/word/libel','https://en.wiktionary.org/wiki/libelous']),
E('libellous','/ˈlaɪbələs/','诽谤性的〔英式常用拼写〕','和 libelous 指向同一种内容性质，只是英式拼写多保留一个 l。','libel + -ous，英式常写 libellous；双写 l 不增加新的词义。',LI+[['libel + -ous；英式常双写 l','libellous：诽谤性的']],'libellous 常见于英国新闻、出版和法律语境。看到 a libellous claim，先把它理解为“诽谤性说法”，不要因为多出一个字母就另找一个词根。写作时与所用英美拼写习惯保持一致即可。','a libellous claim；libellous remarks；a potentially libellous passage。','libellous 与 libelous 主要是拼写差异；liberal“自由的、开明的”等属于另一条词源，不能混在一起。',('The publisher removed a potentially libellous passage from the manuscript.','出版方从书稿中删掉了一段可能构成诽谤的文字。'),('The reviewer described the accusation as libellous.','评论者称那项指控具有诽谤性。'),sources=['https://en.wiktionary.org/wiki/libellous','https://www.etymonline.com/word/libel']),
E('libretto','英 /lɪˈbretəʊ/；美 /lɪˈbretoʊ/','歌剧等音乐作品的文字脚本','把舞台上要唱、要说的文字拿出来，和负责旋律的乐谱分开看。','意大利语 libro“书” + 小称后缀 -etto → libretto“小册子”；英语借来用于音乐作品的文字。',LT,'libretto 可以指装着文字的小册子，也可以直接指那套文字本身。歌剧里人物说什么、唱什么、情节怎样展开，要靠 libretto；旋律、节奏和配器则属于音乐层面。实际创作中两者往往互相配合。','write a libretto；the libretto of an opera；read the libretto。','score 是乐谱，libretto 是文字脚本；lyrics 常指歌词，libretto 还可能包括对白、舞台说明等。复数可用 librettos 或 libretti。',('I read the libretto before going to the opera.','去听歌剧前，我先读了它的文字脚本。'),('The composer asked for a shorter libretto.','作曲家希望把脚本缩短一些。'),sources=['https://www.etymonline.com/word/libretto','https://en.wiktionary.org/wiki/libretto']),
E('librettist','/lɪˈbretɪst/','歌剧等音乐作品的脚本作者','在音乐作品的合作里，主要负责人物要说、要唱的那套文字的人。','libretto 去末尾 o + -ist“从事者” → librettist。',LT+[['libretto + -ist → librettist','写这类文字脚本的人']],'librettist 写的是 libretto，可以负责把原有小说或故事改成适合歌唱和舞台的文字。composer 主要负责音乐。同一个人可以兼任两者，但两个词描述的是不同工作。','the composer and librettist；work with a librettist。','librettist 不等于 librarian：前者写舞台文字，后者从事图书馆工作。playwright 是剧作家，范围与重点也不同。',('The librettist adapted the novel into three short acts.','脚本作者把那部小说改编成了简短的三幕。'),('The composer and librettist revised the ending together.','作曲家和脚本作者一起修改了结尾。'),sources=['https://www.merriam-webster.com/dictionary/librettist','https://en.wiktionary.org/wiki/librettist']),
]
ROOT=dict(id='C0671',meaning='书、书写材料；藏书、文字脚本与书面陈述',core='LIBR = BOOK',image='同一本“小书”的画面可以走向不同用途：集中收藏成 library，给舞台表演提供文字成 libretto，书面陈述的一条支线变成 libel。',intro='本组的拉丁源词是 liber“书”，属格 libri，因而常见 libr-。这个词也有“树的内皮”的旧义，连接书写材料的历史；更远的史前来源并不完全确定。它与表示“自由”的拉丁 līber 是不同的词，不要靠“图书馆让人自由”把两个词源硬连起来。',forms='library 经法语藏书相关形式传来；libel 经拉丁小称 libellus；libretto 经意大利语 libro 的小称。三者是同一“书”源头的不同路线，不是 library 依次缩短出来。librarian 与 librarianship 是职业及实践；interlibrary 的 inter- 表示馆际之间。',branches=[['收藏、查找和使用资料','library, librarian, librarianship, interlibrary'],['小册子到书面诽谤','libel, libelous, libellous'],['音乐舞台上的文字','libretto, librettist']],contrasts='library 是图书馆，bookstore 是书店。libretto 负责文字，score 是乐谱。libel 的现代负面意义经过后来的语义变化，不能倒过来说拉丁 liber 本身就有诽谤义。',practice='The librarian found a copy of the libretto through an interlibrary loan.\n\n图书馆员通过馆际互借找到了那份歌剧脚本。',words=[w['word'] for w in W]+['interlibrary'],exclude={})
