 for name,data in [('roots_libr',[ROOT]),('words_libr',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 x=next(w for w in W if w['word']=='libellous')
